window.DATA={"modules": [{"id": "comec", "name": "Prensa hidráulica COMEC 250 ton", "sections": [{"id": "A", "title": "A — REQUISITOS GERAIS (DL 50/2005, Anexo I)", "items": [{"id": "A.1", "text": "Sistemas de comando — identificação clara em PT ou simbologia normalizada; posições de funcionamento visíveis", "hint": "Verificar cada botão/seletor: tem etiqueta legível? Ex: START / STOP / SUBIDA / DESCIDA / ALMOFADA. Botões desgastados sem legenda = NC. Simbologia ISO 7000 é aceite como alternativa a texto."}, {"id": "A.2", "text": "Arranque do equipamento — exige ação intencional; sem arranque acidental por reposição de energia", "hint": "Testar: retirar e repor alimentação elétrica — a máquina não pode arrancar sozinha. O operador tem de premir activamente o comando. Verificar se existe função de re-arranque automático após falha de energia."}, {"id": "A.3", "text": "Paragem normal — dispositivo acessível e funcional; paragem prioritária ao arranque", "hint": "Identificar botão STOP principal. Testar: premir STOP durante descida — o cilindro deve parar. A paragem deve ter prioridade sobre qualquer comando de arranque simultâneo."}, {"id": "A.4", "text": "Paragem de emergência — botão vermelho/fundo amarelo acessível ao operador; retorno manual após atuação (EN ISO 13850)", "hint": "Verificar: existe botão de emergência (cogumelo vermelho, fundo amarelo)? Está ao alcance do operador sem se deslocar? Após premir, a máquina não pode reiniciar sem desbloqueio manual do botão + ação intencional de reset. Testar funcionamento."}, {"id": "A.5", "text": "Estabilidade — fixação ao pavimento adequada; sem oscilação durante ciclo", "hint": "Com 19.000 kg esta máquina não oscila facilmente, mas verificar: parafusos de fixação ao pavimento presentes e sem folga visível. Observar durante ciclo se há vibração anormal nas colunas ou na estrutura."}, {"id": "A.6", "text": "Rutura — estado do chassis, colunas, travessas e guias sem fissuras ou deformações visíveis", "hint": "Inspecionar visualmente as 4 colunas cilíndricas: sem fissuras longitudinais, corrosão profunda ou marcas de impacto. Verificar as porcas de aperto das colunas (normalmente no topo e base). Inspecionar a travessa superior e a mesa inferior."}, {"id": "A.7", "text": "Projeções — proteção contra projeção de material, peças e salpicos de óleo hidráulico a alta pressão", "hint": "Verificar os 3 lados não operativos (traseiro + 2 laterais): existe algum resguardo em chapa ou rede metálica ancorado nas colunas? Para salpicos de óleo: mangueiras e uniões têm mangas anti-salpico ou defletores? A zona das ligações hidráulicas está protegida?"}, {"id": "A.8", "text": "Emanações / fugas — inexistência de fugas de óleo hidráulico visíveis", "hint": "Inspecionar o pavimento sob a máquina: manchas de óleo recentes? Verificar visualmente todas as mangueiras ao longo do percurso, as uniões roscadas, o cilindro principal e o cilindro da almofada. Verificar o depósito e as ligações da unidade de potência. Registar localização exata de qualquer fuga."}, {"id": "A.9", "text": "Riscos de contacto mecânico — zona de prensagem protegida por resguardo com interlocking ou dispositivo equivalente", "hint": "Verificar o lado frontal (operador): existe resguardo físico com interruptor de segurança, cortina de luz ou comando bimanual? Os 3 lados restantes: têm resguardo fixo? A zona da almofada (inferior) está acessível durante ciclo? Testar interlocking se existir: abrir resguardo com máquina em ciclo — deve parar."}, {"id": "A.10", "text": "Iluminação — zona de trabalho com iluminação suficiente; sem sombras na zona operativa", "hint": "Avaliar subjetivamente: o operador consegue ver claramente o posicionamento da peça na matriz com a iluminação existente? Existe luminária dedicada à máquina ou depende da iluminação geral da nave?"}, {"id": "A.11", "text": "Temperatura — superfícies quentes do sistema hidráulico protegidas ou sinalizadas", "hint": "Após funcionamento prolongado, o motor e o depósito hidráulico atingem temperatura elevada. Verificar se estão acessíveis ao toque involuntário. Temperatura normal do óleo: até ~60°C. Verificar se existe termóstato de proteção por sobreaquecimento."}, {"id": "A.12", "text": "Dispositivos de alerta — sinalização de arranque e avisos de perigo visíveis e legíveis", "hint": "Verificar: existe sinal sonoro ou luminoso de arranque? Os avisos colados/pintados na máquina ainda são legíveis? Sinais de EPI obrigatório (luvas, óculos, calçado) presentes?"}, {"id": "A.13", "text": "Manutenção — pontos acessíveis com máquina parada; procedimento LOTO implementado", "hint": "Verificar: existe procedimento escrito de LOTO afixado? Existe cadeado disponível para bloquear o interruptor geral? Os pontos de lubrificação das colunas são acessíveis sem entrar na zona de perigo? Registar se há manutenção feita com máquina energizada."}, {"id": "A.14", "text": "Riscos elétricos — quadro elétrico identificado; cablagem sem danos; ligação à terra verificada", "hint": "Verificar: quadro elétrico tem sinal de perigo elétrico (raio amarelo)? Porta do quadro fecha e não tem danos? Inspecionar cabos visíveis: isolamento sem fissuras, sem contacto com óleo ou superfícies quentes. Verificar ligação à terra na carcaça do motor."}, {"id": "A.15", "text": "Riscos de incêndio — sem fontes de ignição próximas de mangueiras e depósito hidráulico", "hint": "Óleo hidráulico mineral tem ponto de inflamação >140°C — risco baixo em condições normais. Verificar se há trabalhos de soldadura ou corte próximos sem proteção das mangueiras. Extintor adequado (CO2 ou pó) próximo?"}, {"id": "A.16", "text": "Riscos de explosão", "hint": ""}, {"id": "A.17", "text": "Fontes de energia — corte geral elétrico com bloqueio na posição desligado (LOTO)", "hint": "Localizar o interruptor geral / disjuntor principal. Verificar: tem furo ou previsão para cadeado de bloqueio na posição OFF? Se não tem, é NC — a solução é instalar um bloqueador de disjuntor (acessório de ~5€ disponível em catálogos de segurança)."}, {"id": "A.18", "text": "Sinalização de segurança — sinais de EPI, zonas de perigo e instruções visíveis", "hint": "Verificar presença e legibilidade de: sinal de EPI obrigatório (luvas, calçado, óculos), sinal de proibição de acesso durante ciclo, instruções básicas de operação. Sinais desbotados ou arrancados = NC."}]}, {"id": "B", "title": "B — SISTEMA HIDRÁULICO (específico prensa hidráulica COMEC 723C — 250 ton)", "items": [{"id": "B.1", "text": "Pressão máxima de serviço marcada e visível; manómetro presente, legível e em bom estado", "hint": "Localizar o(s) manómetro(s) — normalmente no bloco de válvulas ou na unidade de potência. A agulha está dentro do arco verde/limite definido? O vidro está intacto? Existe marcação da pressão máxima admissível no manómetro ou junto dele?"}, {"id": "B.2", "text": "Válvula(s) de alívio de pressão presentes, funcionais e reguladas para pressão máxima admissível", "hint": "Normalmente uma válvula de alívio no circuito principal e outra no circuito da almofada. Verificar visualmente se existem — são válvulas com porca de regulação e contraporca. Não testar sem instrução técnica. Registar se há evidência de afinação recente."}, {"id": "B.3", "text": "Mangueiras hidráulicas sem abrasão, fissuras, dobragens acentuadas ou danos; uniões em bom estado", "hint": "Inspecionar todo o percurso das mangueiras. Sinais de NC: revestimento exterior com cortes ou abrasão, manchas de óleo húmidas nas uniões, mangueiras em contacto com arestas metálicas, raios de curvatura muito apertados. Atenção às mangueiras junto ao cilindro da almofada (zona inferior, menos visível)."}, {"id": "B.4", "text": "Mangueiras protegidas em zonas de tráfego, impactos ou contacto com superfícies quentes", "hint": "Verificar se mangueiras que passam por zonas de circulação têm proteção mecânica (calha, espiral metálica). Verificar se não estão em contacto direto com o motor elétrico ou outras superfícies quentes."}, {"id": "B.5", "text": "Depósito hidráulico — nível de óleo visível; tampas de enchimento identificadas", "hint": "Localizar o depósito (normalmente na unidade de potência lateral). O visor/indicador de nível está limpo e o óleo visível? O nível está entre MIN e MAX? A tampa de enchimento tem filtro/respirador? Óleo com aparência leitosa indica contaminação com água."}, {"id": "B.6", "text": "Sistema de filtragem — filtro de retorno presente; estado OK", "hint": "Verificar se existe filtro de retorno na linha de volta ao depósito. Se tiver indicador de colmatação (manómetro diferencial ou indicador visual), verificar se está no verde. Registar data da última substituição se conhecida."}, {"id": "B.7", "text": "Cilindro do embutidor (principal) — sem fugas externas na camisa ou haste; vedantes sem degradação", "hint": "Inspecionar a haste do cilindro principal (a que desce): tem óleo visível na superfície além de filme fino normal? Existe acumulação de óleo na base do cilindro ou no colarinho do vedante? Haste com riscas profundas ou corrosão danifica os vedantes rapidamente."}, {"id": "B.8", "text": "Cilindro da almofada (inferior) — sem fugas; haste sem danos", "hint": "O cilindro da almofada fica sob a mesa — zona menos visível. Usar lanterna para inspecionar. Mesmos critérios do B.7. Verificar também se a almofada sobe e desce de forma suave e controlada durante teste manual."}, {"id": "B.9", "text": "Calços de segurança (apoios mecânicos) disponíveis para bloqueio do cilindro em manutenção", "hint": "Verificar se existem calços ou blocos de madeira/metal resistentes para colocar sob a mesa móvel quando o cilindro está descido durante manutenção. Sem calços, qualquer falha hidráulica com operador na zona = catastrófico."}, {"id": "B.10", "text": "Motor da unidade de potência — sem vibrações anormais; temperatura normal; sem ruídos de cavitação", "hint": "Ligar a unidade de potência e observar: ruído de bomba hidráulica normal é contínuo e regular. Ruído tipo \"matraquear\" ou \"assobiar\" indica cavitação (ar no circuito ou nível de óleo baixo). Vibração excessiva na unidade indica desgaste de bomba ou acoplamento."}, {"id": "B.11", "text": "Calços de segurança disponíveis e procedimento de uso conhecido pelo operador", "hint": "Confirmar fisicamente se existem calços e onde estão guardados. Perguntar ao operador se sabe quando e como os usar. Se não souber, NC por ausência de instrução."}, {"id": "B.12", "text": "FDS do fluido hidráulico disponível; resíduos com código LER correto (13 01 10* para óleo mineral)", "hint": "Verificar se há FDS do óleo hidráulico utilizado. Verificar se os registos de eliminação de óleo usado existem e usam o código LER correto. Óleo de prensa desta dimensão gera volume significativo de resíduo perigoso."}]}, {"id": "C", "title": "C — PROTEÇÃO DA ZONA DE PRENSAGEM (EN ISO 13857 + EN ISO 13849-1)", "items": [{"id": "C.1", "text": "Resguardos nos 3 lados não operativos (traseiro + 2 laterais) — fixos, removíveis só com ferramenta", "hint": "Verificar se existem resguardos em chapa ou rede metálica ancorados nas colunas nos lados traseiro e laterais. Num prensa de 4 colunas com acesso pelas 4 frentes isto é frequentemente omitido. Se existirem: tentam ser removidos à mão? Devem exigir ferramenta (parafusos)."}, {"id": "C.2", "text": "Lado frontal (operador) — resguardo com interlocking, cortina de luz ou comando bimanual", "hint": "Identificar qual o dispositivo existente no lado do operador. Opções: (a) resguardo físico com interruptor de segurança na dobradiça; (b) cortina de luz emissora/recetora nas laterais da abertura; (c) comando bimanual que exige 2 mãos simultâneas. Se nenhum: NC crítico."}, {"id": "C.3", "text": "Interlocking testado funcionalmente — abertura durante ciclo provoca paragem imediata", "hint": "Se existir resguardo com interruptor: abrir o resguardo manualmente durante descida controlada — a máquina deve parar imediatamente. Se não parar, o interlocking está inutilizado ou avariado = NC crítico."}, {"id": "C.4", "text": "Distâncias de segurança entre resguardo e zona de perigo conformes EN ISO 13857", "hint": "Se existir abertura entre o resguardo e a zona de prensagem: verificar que não permite introdução de mão ou dedo até à zona de perigo. Regra prática: abertura <6mm não permite entrada de dedo; entre 6-35mm permite dedo mas não mão; acima disso exige distância mínima calculada."}, {"id": "C.5", "text": "Nenhum dispositivo de segurança neutralizado, retirado ou inutilizado", "hint": "Verificar se há cabos de interruptores desligados, sensores com fita isoladora, resguardos retirados para facilitar a operação. Perguntar ao operador se algum dispositivo \"não funciona\" ou \"foi retirado\". Este é frequentemente o NC mais grave encontrado."}, {"id": "C.6", "text": "Modo automático — verificar condições de acesso durante ciclos consecutivos", "hint": "O catálogo desta COMEC refere modo automático (ciclos sucessivos sem intervenção). Se este modo for usado: como é que o operador fica protegido durante ciclos consecutivos? Deve existir proteção perimetral que impeça entrada na zona durante operação automática."}]}, {"id": "D", "title": "D — DISPOSITIVOS DE SEGURANÇA E CONTROLO", "items": [{"id": "D.1", "text": "Paragem de emergência testada — actua sobre sistema hidráulico e elétrico; sem movimento residual excessivo do cilindro", "hint": "Premir a paragem de emergência durante descida a velocidade de trabalho. Medir/estimar a distância percorrida após activação. Para 250 ton, algum movimento residual é esperado (inercia + pressão) mas deve ser mínimo. Registar distância aproximada."}, {"id": "D.2", "text": "Funções de subida/descida independentes para embutidor e almofada — comandos claramente identificados", "hint": "Esta máquina tem 2 cilindros independentes. Verificar se os comandos de subida/descida de cada um estão claramente distinguidos e identificados. Confusão entre comandos pode resultar em activação errada do cilindro."}, {"id": "D.3", "text": "Modo manual (regulação) — permite movimentos lentos e controlados para acerto de ferramentas", "hint": "Verificar se existe seletor de modo Manual/Semiautomático/Automático. No modo manual, a velocidade deve ser reduzida para permitir acerto seguro das ferramentas. Testar se a velocidade é efetivamente reduzida neste modo."}, {"id": "D.4", "text": "Pedal de comando (se existente) — protegido contra accionamento acidental", "hint": "Se existir pedal: tem chapéu/protetor metálico que impede ser pisado acidentalmente por queda de material ou passagem de empilhador? Cabo do pedal em bom estado sem danos?"}]}, {"id": "E", "title": "E — FONTES DE ENERGIA E LOTO (Pontos 7 e 8 do DL 50/2005, Anexo I)", "items": [{"id": "E.1", "text": "Corte geral da energia elétrica com possibilidade de bloqueio (cadeado) na posição desligado", "hint": "Localizar o disjuntor/interruptor geral. Verificar se tem orifício para cadeado ou previsão de bloqueador. Se não tiver: solução simples é um bloqueador de disjuntor universal (~5-15€ em distribuidores de material elétrico)."}, {"id": "E.2", "text": "Corte geral da pressão hidráulica com bloqueio na posição desligado", "hint": "Verificar se existe válvula de corte manual na linha de pressão principal com possibilidade de bloquear na posição fechada. Alternativa: a despressurização é garantida pelo corte elétrico da bomba? Documentar o procedimento de despressurização completa do circuito."}, {"id": "E.3", "text": "Procedimento LOTO documentado em PT e afixado junto à máquina", "hint": "Verificar se existe instrução escrita passo-a-passo: (1) parar ciclo, (2) premir emergência, (3) desligar interruptor geral, (4) colocar cadeado, (5) descarregar pressão residual, (6) colocar calços. Se não existir = NC — pode ser elaborado internamente."}, {"id": "E.4", "text": "Confirmar despressurização completa antes de qualquer trabalho na zona de prensagem", "hint": "Verificar se o procedimento inclui passo de confirmação de pressão zero no manómetro antes de entrada na zona. Com 250 ton, pressão residual no circuito após paragem pode ser significativa e perigosa."}]}, {"id": "F", "title": "F — RISCOS ELÉTRICOS (Pontos 5 e 6 do DL 50/2005, Anexo I)", "items": [{"id": "F.1", "text": "Quadro elétrico com sinal de perigo elétrico visível (EN ISO 7010 — W012)", "hint": "Verificar se a porta do quadro tem o triângulo amarelo com raio. Se não tiver = NC fácil de corrigir (autocolante normalizado). Verificar se a inscrição \"PERIGO ELÉTRICO\" ou símbolo está legível."}, {"id": "F.2", "text": "Quadro elétrico fechado durante operação; sem danos na porta ou vedação", "hint": "A porta deve fechar completamente e de preferência com fecho. Verificar se há aberturas, furos ou entradas de cabo sem vedação — numa prensa com óleo, a proteção IP do quadro é importante."}, {"id": "F.3", "text": "Cablagem elétrica sem danos; isolamento íntegro; sem contacto com óleo ou calor", "hint": "Inspecionar cabos visíveis externamente ao quadro: isolamento sem fissuras, sem zonas peladas, não passam sobre superfícies quentes, não estão em poça de óleo. Cabo do pedal/bimanual merece atenção especial — está sujeito a movimento e abrasão."}, {"id": "F.4", "text": "Ligação à terra da carcaça do motor e da estrutura da máquina verificável visualmente", "hint": "Verificar se existe cabo de terra visível na carcaça do motor elétrico. Verificar se a estrutura da máquina tem ligação à terra (cabo amarelo/verde para eléctrodo ou estrutura do edifício)."}]}, {"id": "G", "title": "G — DOCUMENTAÇÃO (Ponto 10 do DL 50/2005, Anexo I)", "items": [{"id": "G.1", "text": "Chapa de identificação do equipamento — fabricante, modelo, nº série, ano, capacidade máxima", "hint": "ATENÇÃO: esta máquina não tem chapa de identificação — NC confirmado. Recomendação: fabricar e instalar chapa metálica com dados do catálogo COMEC e registos internos IETA (modelo 723C 250-180, nº interno MAQ-IETA-001, ano estimado ~1985, força máx. 250 ton)."}, {"id": "G.2", "text": "Manual de instruções em português disponível e acessível ao operador", "hint": "O documento existente é um catálogo comercial, não um manual de operação/segurança. NC — é necessário elaborar instruções internas de operação e segurança em PT com base no catálogo e no conhecimento do operador. Não existe obrigação de CE para máquinas anteriores a 1995."}, {"id": "G.3", "text": "Máquina anterior a 01/01/1995: avaliação de conformidade por equivalência documentada (Anexo II DL 50/2005)", "hint": "ATENÇÃO: esta máquina tem ~40 anos — não está sujeita a marcação CE mas deve cumprir o Anexo I do DL 50/2005. O presente relatório constitui a avaliação das condições de segurança exigida pelo DL 50/2005."}, {"id": "G.4", "text": "Plano de manutenção preventiva existente e atualizado", "hint": "Verificar se existe plano escrito com periodicidade de: substituição de óleo hidráulico, inspeção de mangueiras, lubrificação das colunas, verificação de vedantes. Registos de manutenção existentes devem ser listados no relatório."}, {"id": "G.5", "text": "Registos de inspeções e intervenções de manutenção disponíveis", "hint": "Consultar registos existentes: que trabalhos foram feitos, por quem e quando. Documentar no relatório o historial disponível. A ausência de registos é ela própria uma NC de documentação."}, {"id": "G.6", "text": "Instruções de operação e segurança elaboradas internamente em PT", "hint": "Se não existir manual adequado: elaborar instrução interna com: sequência de arranque/paragem, EPI obrigatórios, proibições (ex: nunca entrar na zona de prensagem com máquina energizada), procedimento de emergência e contactos."}, {"id": "G.7", "text": "FDS do fluido hidráulico disponível; código LER correto nos registos de resíduos", "hint": "Identificar o fluido usado (marca e referência no depósito). FDS deve estar acessível. Resíduos de óleo hidráulico mineral = LER 13 01 10* (resíduo perigoso). Verificar se a eliminação é feita por operador licenciado."}, {"id": "G.8", "text": "Lista de EPI obrigatórios afixada junto à máquina; EPI disponíveis e em bom estado", "hint": "Verificar se existe lista de EPI afixada na máquina. Confirmar fisicamente disponibilidade: calçado de segurança, luvas (resistentes a óleo), óculos de proteção. Verificar estado de conservação dos EPI disponíveis."}]}, {"id": "H", "title": "H — REQUISITOS COMPLEMENTARES (equipamentos móveis e de elevação — NA para prensa fixa)", "items": [{"id": "H.1", "text": "Equipamentos que transportam trabalhadores / capotamento", "hint": ""}, {"id": "H.2", "text": "Transmissão de energia (equipamentos automotores)", "hint": ""}, {"id": "H.3", "text": "Equipamentos de elevação ou transporte de trabalhadores", "hint": ""}]}], "note": "Checklist completo e próprio desta prensa (secções A a H), anterior à estrutura modular.", "standalone": true, "multi": false}, {"id": "elevacao", "name": "Elevação e Movimentação", "sections": [{"id": "B", "title": "B — PONTE ROLANTE E GUINCHOS (aparelhos de elevação fixos ou suspensos)", "items": [{"id": "B.1", "text": "Placa de capacidade máxima (SWL / carga máxima admissível) visível e legível na estrutura e/ou no gancho", "hint": "Verificar se a carga máxima está marcada de forma legível junto ao comando ou na estrutura do aparelho."}, {"id": "B.2", "text": "Gancho com trinco de segurança (pestana) funcional; sem deformação, abertura anormal, fissuras ou desgaste na rosca", "hint": "Testar o fecho do trinco. Medir/observar abertura do gancho — um gancho \"aberto\" além do previsto pelo fabricante é NC."}, {"id": "B.3", "text": "Cabo de aço ou corrente de elevação sem fios partidos, deformações, achatamento, corrosão ou desgaste visível", "hint": "Inspecionar todo o comprimento do cabo/corrente, incluindo a zona junto ao tambor/gancho. Critério de descarte depende do fabricante/norma aplicável — confirmar com entidade de inspeção se houver dúvida."}, {"id": "B.4", "text": "Tambor e polias sem desgaste anormal; enrolamento do cabo correto, sem sobreposição ou cruzamento de espiras", "hint": "Observar o cabo enrolado no tambor durante um ciclo de subida — não deve saltar da ranhura nem cruzar-se."}, {"id": "B.5", "text": "Fins de curso (limitadores) de subida e de translação funcionais", "hint": "Testar em vazio: aproximar lentamente do limite e confirmar paragem automática antes do batente mecânico."}, {"id": "B.6", "text": "Travão de carga funcional — a carga suspensa não desce sozinha com o comando em repouso", "hint": "Suspender uma carga de teste, largar o comando e observar durante alguns segundos se há descida (\"deslizamento\")."}, {"id": "B.7", "text": "Comando (botoneira ou rádio-comando) com identificação clara dos movimentos; botão de emergência funcional", "hint": "Verificar etiquetagem dos botões (subir/descer/translação) e testar a paragem de emergência do comando."}, {"id": "B.8", "text": "Sinalização de movimento (sonora/luminosa) e via/zona de manobra identificada no solo, quando aplicável", "hint": "Aplicável sobretudo a pontes rolantes com zona de trabalho partilhada com peões."}, {"id": "B.9", "text": "Estrutura de suporte, carril e fixações sem deformações, fissuras, corrosão ou folgas visíveis", "hint": "Inspecionar vigas, carris e ligações à estrutura do edifício."}, {"id": "B.10", "text": "Proibição de circulação/permanência sob carga suspensa sinalizada; zona de manobra sem obstruções", "hint": "Verificar sinalização no pavimento/parede e se a zona está de facto desimpedida na prática."}, {"id": "B.11", "text": "Registo de inspeção/exame periódico do aparelho de elevação disponível e dentro do prazo", "hint": "Confirmar periodicidade e entidade responsável aplicável a este tipo de equipamento — a validar internamente/com entidade certificadora."}, {"id": "B.12", "text": "Plano de manutenção e lubrificação do cabo/corrente e dos órgãos de transmissão existente", "hint": "Verificar registo de última lubrificação e substituição de cabo/corrente, se aplicável."}]}, {"id": "C", "title": "C — EMPILHADORES ELÉTRICOS E STACKERS (equipamentos automotores)", "items": [{"id": "C.1", "text": "Operador com formação/carta de condução de empilhadores válida", "hint": "Confirmar registo de formação do operador. Ausência de formação documentada = NC, independentemente da experiência do operador."}, {"id": "C.2", "text": "Cinto de segurança presente e em uso, quando o modelo o prevê", "hint": "Aplicável a empilhadores de condutor sentado. Verificar estado do cinto e se é efetivamente utilizado."}, {"id": "C.3", "text": "Buzina, sinal sonoro de marcha-atrás e sinalização luminosa (rotativo/estroboscópio) funcionais", "hint": "Testar cada dispositivo. Em zonas de cruzamento com peões, a ausência de sinal de marcha-atrás é NC prioritário."}, {"id": "C.4", "text": "Travões de serviço e de estacionamento funcionais", "hint": "Testar travagem em vazio e travão de estacionamento em rampa/inclinação, se existir no percurso."}, {"id": "C.5", "text": "Garfos sem deformações, fissuras ou desgaste excessivo; travas de fixação ao mastro funcionais", "hint": "Verificar alinhamento dos garfos entre si e o sistema de bloqueio ao porta-garfos."}, {"id": "C.6", "text": "Mastro e correntes de elevação sem folgas anormais, fissuras ou falta de lubrificação", "hint": "Observar durante um ciclo completo de elevação — movimento deve ser suave, sem solavancos nem ruído anormal."}, {"id": "C.7", "text": "Zona de carregamento de bateria com ventilação adequada; bornes, fichas e cabos de carregamento em bom estado; EPI para manuseamento de eletrólito disponível", "hint": "Baterias de tração libertam hidrogénio durante a carga — confirmar ventilação da zona e ausência de fontes de ignição próximas."}, {"id": "C.8", "text": "Espelhos/visibilidade traseira e lateral adequados; iluminação de trabalho funcional", "hint": "Avaliar campo de visão do operador, sobretudo em marcha-atrás e com carga que limite a visibilidade frontal."}, {"id": "C.9", "text": "Placa de capacidade de carga (diagrama carga/altura/centro de carga) visível e legível", "hint": "Verificar se a placa está presente e legível na cabine ou junto ao painel de comando."}, {"id": "C.10", "text": "Vias de circulação em bom estado, sem irregularidades relevantes no piso", "hint": "Percurso habitual do equipamento sem buracos, ressaltos ou obstáculos fixos não sinalizados."}, {"id": "C.11", "text": "Sinalização de vias de circulação, cruzamentos e zonas partilhadas com peões", "hint": "Verificar marcação no pavimento, espelhos convexos em cruzamentos cegos, e separação física onde exista risco de atropelamento."}, {"id": "C.12", "text": "Registo de inspeções e manutenção periódica disponível", "hint": "Consultar histórico de manutenção — filtros, óleo hidráulico, travões, pneus/rodas."}]}, {"id": "D", "title": "D — PORTA-PALETES E STACKERS MANUAIS (movimentação manual/semi-elétrica)", "items": [{"id": "D.1", "text": "Rodas e rodízios sem desgaste excessivo, fissuras ou folgas no eixo", "hint": "Rodas gastas de forma irregular dificultam a manobra e aumentam o esforço/risco de lesão do operador."}, {"id": "D.2", "text": "Sistema de elevação (bomba manual ou grupo hidráulico elétrico) sem fugas visíveis; eleva e desce de forma controlada", "hint": "Verificar ausência de óleo no pavimento sob o equipamento e suavidade do movimento de subida/descida."}, {"id": "D.3", "text": "Válvula de descida controlada — a carga não desce em queda livre", "hint": "Elevar em vazio e testar a descida — deve ser gradual e controlada, nunca brusca."}, {"id": "D.4", "text": "Garfos sem deformações; travão de roda (quando existente) funcional", "hint": "Verificar alinhamento dos garfos e, em stackers, o sistema de travagem das rodas de apoio."}, {"id": "D.5", "text": "Placa de capacidade de carga visível e legível", "hint": "Confirmar que a carga máxima admissível está identificada no equipamento."}, {"id": "D.6", "text": "Para equipamentos elétricos: bateria, carregador, comandos e sinalização sonora/luminosa em bom estado", "hint": "Aplicar os critérios equivalentes a C.3/C.4/C.7 quando o porta-paletes ou stacker for elétrico."}, {"id": "D.7", "text": "Pega/timão sem folgas; comandos de subida/descida/travagem claramente identificados", "hint": "Testar o comando de travagem no timão (quando existente) e verificar folga excessiva na articulação."}]}], "note": "Este módulo insere-se no \"Checklist de Segurança de Equipamentos de Trabalho — Núcleo Geral IETA\", entre a Secção A e a Secção E, sempre que o equipamento em avaliação for um aparelho de elevação e/ou um equipamento de movimentação de cargas. Está dividido em três blocos consoante o tipo de equipamento: B (aparelhos de elevação fixos/suspensos), C (equipamentos automotores) e D (equipamentos de movimentação manual/semi-elétrica). Aplicar apenas o bloco correspondente ao equipamento em avaliação; os restantes marcam-se como NA. Nota: os pontos de periodicidade de inspeção/exame legalmente exigi", "standalone": false, "multi": true}, {"id": "conformacao", "name": "Conformação Mecânica", "sections": [{"id": "B", "title": "B — SISTEMA MECÂNICO DE ACIONAMENTO (embraiagem, volante de inércia, travão)", "items": [{"id": "B.1", "text": "Volante de inércia protegido por resguardo fixo, impedindo contacto com peças em rotação", "hint": "Verificar se o volante está totalmente coberto ou tem resguardo perimetral fixo, removível só com ferramenta."}, {"id": "B.2", "text": "Correias e polias de transmissão com resguardo fixo; correias sem fissuras, cortes ou folga excessiva", "hint": "Inspecionar visualmente o estado das correias e o resguardo de proteção da transmissão."}, {"id": "B.3", "text": "Embraiagem engata e desengata de forma limpa, sem escorregamento, patinagem ou ruído anormal", "hint": "Observar um ciclo completo. Escorregamento da embraiagem é sinal de desgaste e pode comprometer a paragem no ponto certo."}, {"id": "B.4", "text": "Travão do volante/cursor funcional — imobiliza o cursor dentro do ângulo/tempo especificado após o comando de paragem", "hint": "Testar a paragem a meio-curso. O cursor não deve continuar a descer de forma significativa após o comando de STOP."}, {"id": "B.5", "text": "Tempo de paragem do travão medido/conhecido, necessário para validar a distância de segurança da proteção frontal", "hint": "Sem este valor não é possível confirmar se a distância entre o resguardo/cortina de luz e a zona de perigo cumpre a EN ISO 13857 — medir com equipamento adequado ou solicitar a fabricante/entidade especializada."}, {"id": "B.6", "text": "Dispositivo de anti-repetição (anti-repeat) ativo — impede um segundo golpe do cursor em caso de falha da embraiagem/travão ou de o comando ficar acidentalmente acionado", "hint": "Confirmar com o fabricante ou por inspeção do circuito de comando se este dispositivo existe. A ausência de anti-repetição é um dos riscos mais graves e mais frequentemente esquecidos em prensas mecânicas antigas."}, {"id": "B.7", "text": "Lubrificação do volante, chumaceiras, excêntrico/biela conforme plano de manutenção", "hint": "Verificar registo de lubrificação e se os pontos de lubrificação são acessíveis sem entrar na zona de perigo."}, {"id": "B.8", "text": "Indicador de posição do cursor (Ponto Morto Superior / Ponto Morto Inferior) visível ao operador", "hint": "Verificar existência de marca ou indicador que permita ao operador confirmar a posição do cursor antes de intervir."}, {"id": "B.9", "text": "Balancés manuais/de fricção: mecanismo de fricção sem folgas excessivas; pega/manípulo de acionamento em bom estado", "hint": "Aplicável apenas a balancés de acionamento manual. Testar folga entre o disco de fricção e o volante."}]}, {"id": "C", "title": "C — PROTEÇÃO DA ZONA DE PRENSAGEM (EN ISO 13857 + EN ISO 13849-1)", "items": [{"id": "C.1", "text": "Resguardos nos lados não operativos — fixos, removíveis só com ferramenta", "hint": "Verificar se existem resguardos em chapa ou rede metálica nos lados traseiro e laterais, ancorados à estrutura da máquina."}, {"id": "C.2", "text": "Lado frontal (operador) — resguardo com interlocking, cortina de luz ou comando bimanual", "hint": "Identificar o dispositivo existente: (a) resguardo físico com interruptor de segurança; (b) cortina de luz; (c) comando bimanual exigindo 2 mãos simultâneas. Se nenhum: NC crítico."}, {"id": "C.3", "text": "Interlocking testado funcionalmente — abertura durante ciclo provoca paragem imediata", "hint": "Abrir o resguardo manualmente durante um ciclo controlado — a máquina deve parar de imediato. Se não parar, o interlocking está inutilizado ou avariado = NC crítico."}, {"id": "C.4", "text": "Distâncias de segurança entre resguardo/cortina de luz e zona de perigo conformes EN ISO 13857", "hint": "A distância mínima depende diretamente do tempo de paragem medido em B.5. Sem esse valor, a distância não pode ser validada com rigor."}, {"id": "C.5", "text": "Nenhum dispositivo de segurança neutralizado, retirado ou inutilizado", "hint": "Verificar cabos de interruptores desligados, sensores com fita isoladora, resguardos retirados para \"facilitar\" a operação. Perguntar ao operador se algum dispositivo \"não funciona\" ou \"foi retirado\"."}, {"id": "C.6", "text": "Modo automático/contínuo — verificar proteção perimetral durante ciclos sucessivos", "hint": "Se a máquina permitir ciclos sucessivos sem intervenção manual, deve existir proteção perimetral que impeça a entrada na zona durante a operação automática."}, {"id": "C.7", "text": "Seletor de modo (golpe único / contínuo) protegido por chave ou código, impedindo alteração não autorizada", "hint": "Verificar se qualquer operador pode mudar de modo livremente ou se a mudança exige chave/autorização — relevante sobretudo em prensas com histórico de \"ajustes\" informais."}]}, {"id": "D", "title": "D — DISPOSITIVOS DE CONTROLO E PARAGEM", "items": [{"id": "D.1", "text": "Paragem de emergência atua sobre a fonte de energia (motor) e sobre a embraiagem/travão em simultâneo, imobilizando o cursor", "hint": "Premir a emergência durante a descida a velocidade de trabalho e confirmar paragem imediata do cursor, não apenas corte do motor."}, {"id": "D.2", "text": "Golpe único garantido mesmo que o comando (pedal/botão) seja mantido acionado continuamente", "hint": "Manter o pedal/botão pressionado após um golpe — a máquina não pode iniciar um segundo golpe sem novo ciclo de acionamento (soltar e voltar a premir)."}, {"id": "D.3", "text": "Modo manual/regulação disponível, com velocidade reduzida, para acerto seguro de ferramentas", "hint": "Verificar existência de seletor Manual/Automático e testar se a velocidade é efetivamente reduzida no modo manual."}, {"id": "D.4", "text": "Pedal de comando (se existente) protegido contra acionamento acidental", "hint": "Verificar se tem chapéu/protetor metálico que impede ser pisado acidentalmente por queda de material ou passagem de equipamento de movimentação."}]}], "note": "Este módulo insere-se no \"Checklist de Segurança de Equipamentos de Trabalho — Núcleo Geral IETA\", entre a Secção A e a Secção E, sempre que o equipamento em avaliação for uma prensa mecânica ou um balancé (mecanismo de acionamento por embraiagem/volante de inércia, em vez de sistema hidráulico). A secção C (proteção da zona de prensagem) é comum a qualquer tipo de prensa — mecânica ou hidráulica — e pode ser reaproveitada tal e qual do módulo de prensas hidráulicas quando aplicável. Nota: o dispositivo de anti-repetição (B.6) e a distância de segurança dependente do tempo de paragem (B.5/C.4)", "standalone": false, "multi": false}, {"id": "quinagem", "name": "Quinagem", "sections": [{"id": "B", "title": "B — SISTEMA DE ACIONAMENTO (normalmente hidráulico)", "items": [{"id": "B.1", "text": "Sistema hidráulico sem fugas de óleo visíveis em mangueiras, uniões e cilindros", "hint": "Inspecionar o pavimento sob a máquina e ao longo das mangueiras/uniões."}, {"id": "B.2", "text": "Nível de óleo hidráulico dentro do intervalo especificado, visível no visor/vareta", "hint": "Verificar visor de nível ou vareta de medição."}, {"id": "B.3", "text": "Travão/válvula de retenção funcional — o cursor não desce sozinho com o comando em repouso", "hint": "Suspender o cursor a meio-curso, largar o comando e observar durante alguns segundos se há descida."}, {"id": "B.4", "text": "Tempo/curso de paragem do cursor conhecido, necessário para dimensionar a distância/curva de segurança do sistema de deteção", "hint": "Sem este valor não é possível validar corretamente a configuração do sistema de deteção ótica (C.4) — confirmar com o fabricante ou medir com equipamento adequado."}, {"id": "B.5", "text": "Comando bimanual ou pedal com proteção contra acionamento acidental", "hint": "Testar comando bimanual (exige as duas mãos em simultâneo) ou verificar chapéu/protetor do pedal."}, {"id": "B.6", "text": "Modo de aproximação lenta (\"inching\"/baixa velocidade) ativo junto ao ponto de contacto com a chapa", "hint": "Verificar se o cursor reduz de facto a velocidade antes do contacto com o material, e não apenas na descida inicial."}, {"id": "B.7", "text": "Paragem de emergência acessível, imobiliza o cursor de imediato", "hint": "Testar durante um ciclo a velocidade de trabalho."}]}, {"id": "C", "title": "C — PROTEÇÃO DA ZONA DE QUINAGEM (deteção ótica)", "items": [{"id": "C.1", "text": "Sistema de deteção ótica (laser/scanner tipo AKAS) ou cortina de luz específica para quinadoras instalado à frente da ferramenta", "hint": "Identificar o dispositivo existente. A ausência de qualquer sistema de deteção na zona de dobragem é NC crítico."}, {"id": "C.2", "text": "Sistema de deteção testado — a descida do cursor é interrompida ao detetar um objeto/mão na zona protegida", "hint": "Testar com objeto de teste (ou seguindo o procedimento do fabricante) em diferentes posições ao longo da ferramenta."}, {"id": "C.3", "text": "Ausência de zonas mortas / pontos cegos na área de deteção", "hint": "Verificar sobretudo nos extremos da ferramenta e em ferramentas segmentadas — zonas onde o feixe pode não cobrir a mão do operador."}, {"id": "C.4", "text": "Distância/curva de segurança do sistema de deteção configurada corretamente para a velocidade e o curso da máquina", "hint": "Depende diretamente do tempo de paragem medido em B.4 — sem esse valor, a configuração não pode ser validada com rigor."}, {"id": "C.5", "text": "Nenhum dispositivo de deteção neutralizado, desligado ou com sensores tapados/sujos", "hint": "Perguntar ao operador se algum sensor \"dá problemas\" ou foi desativado para \"ganhar produtividade\" — sinal de contorno do sistema de segurança."}, {"id": "C.6", "text": "Sinalização de perigo de esmagamento das mãos afixada junto ao posto", "hint": "Confirmar presença e legibilidade da sinalização."}]}, {"id": "D", "title": "D — ESQUADRO TRASEIRO E FERRAMENTAS", "items": [{"id": "D.1", "text": "Esquadro traseiro (back gauge) motorizado sem acesso à zona de movimento durante o posicionamento automático", "hint": "Observar um ciclo de posicionamento — confirmar que a zona de deslocamento do esquadro não é acessível durante o movimento."}, {"id": "D.2", "text": "Percurso do esquadro sem obstruções; fins de curso funcionais", "hint": "Testar aproximação lenta aos limites do curso e confirmar paragem automática."}, {"id": "D.3", "text": "Punção e matriz corretamente fixados, sem folga, alinhados entre si", "hint": "Verificar alinhamento vertical do punção com a matriz e aperto dos elementos de fixação."}, {"id": "D.4", "text": "Ferramentas (punção/matriz) sem fissuras, desgaste excessivo ou deformação", "hint": "Inspecionar visualmente a aresta de trabalho das ferramentas."}, {"id": "D.5", "text": "Troca de ferramentas realizada com a máquina parada e bloqueada (LOTO)", "hint": "Confirmar procedimento seguido pelos operadores durante mudanças de ferramenta — ponto tipicamente esquecido em operações rápidas de série pequena."}]}], "note": "Este módulo insere-se no \"Checklist de Segurança de Equipamentos de Trabalho — Núcleo Geral IETA\", entre a Secção A e a Secção E, sempre que o equipamento em avaliação for uma quinadora. Apesar do acionamento (normalmente hidráulico) ser semelhante ao de uma prensa, a proteção da zona de perigo é diferente: a zona de dobragem tem de permanecer acessível para entrada e saída da chapa, pelo que a proteção é feita por deteção ótica (laser/scanner ou cortina de luz específica) em vez de resguardo físico fechado — por isso não se reaproveita a Secção C dos módulos de prensas. Nota: à semelhança das", "standalone": false, "multi": false}, {"id": "corte", "name": "Corte", "sections": [{"id": "B", "title": "B — CORTE A LASER (tubo e chapa)", "items": [{"id": "B.1", "text": "Cabine/resguardo de proteção contra radiação laser fechada durante o corte; interbloqueio na porta de acesso", "hint": "Verificar se a porta de acesso à cabine tem interruptor de segurança e se a abertura durante o corte interrompe o feixe/o ciclo."}, {"id": "B.2", "text": "Classe do laser identificada; sinalização normalizada de radiação laser afixada (EN ISO 7010 / EN 60825-1)", "hint": "Confirmar classe do equipamento junto do fabricante e se a sinalização de perigo está afixada na cabine e nos acessos."}, {"id": "B.3", "text": "Sistema de extração/filtragem de fumos de corte funcional", "hint": "O fumo de corte a laser contém partículas metálicas finas e pode conter gases de combustão do revestimento do material. Verificar caudal e estado dos filtros."}, {"id": "B.4", "text": "Comando de emergência acessível — interrompe simultaneamente a fonte laser e o movimento dos eixos", "hint": "Testar: a emergência deve cortar o feixe e parar o movimento, não apenas um dos dois."}, {"id": "B.5", "text": "Gases de assistência ao corte (oxigénio, azoto, ar comprimido) — garrafas fixadas verticalmente, válvulas e redutores de pressão em bom estado", "hint": "Verificar fixação das garrafas (correntes/suportes), identificação do gás e ausência de fugas nas uniões."}, {"id": "B.6", "text": "Zona de fixação/carregamento do tubo ou chapa sem risco de esmagamento durante o posicionamento automático", "hint": "Aplicável sobretudo ao carregamento automático de tubos — verificar proteção da zona de avanço/rotação do material."}, {"id": "B.7", "text": "Sinalização luminosa \"laser em funcionamento\" visível a partir do exterior da cabine", "hint": "Confirmar que a sinalização acende sempre que o feixe está ativo, mesmo com a cabine fechada."}, {"id": "B.8", "text": "Janelas/visores da cabine com proteção adequada à classe/potência do laser instalado (quando existentes)", "hint": "Confirmar com o fabricante se os visores existentes são certificados para a classe do laser instalado."}, {"id": "B.9", "text": "Acesso ao interior da cabine restrito durante a operação — chave, código ou procedimento formal necessário", "hint": "Verificar se qualquer operador pode abrir a cabine livremente durante o funcionamento ou se há uma barreira de acesso efetiva."}, {"id": "B.10", "text": "Extintor adequado (CO2 ou pó) disponível próximo, dado o risco de incêndio associado a partículas incandescentes", "hint": "Verificar proximidade e validade do extintor mais próximo da célula de corte."}]}, {"id": "C", "title": "C — CORTE MECÂNICO (serra de tubo, serrote, disco/lâmina)", "items": [{"id": "C.1", "text": "Lâmina/disco de corte com resguardo fixo cobrindo a parte não utilizada no corte", "hint": "Verificar cobertura do disco/lâmina fora da zona ativa de corte — a parte exposta deve ser apenas a estritamente necessária."}, {"id": "C.2", "text": "Resguardo móvel da zona de corte com interlocking, quando existente", "hint": "Testar: abrir o resguardo durante o ciclo deve provocar paragem imediata."}, {"id": "C.3", "text": "Sistema de fixação da peça (mordente/grampo) firme, sem folga, evitando deslizamento ou projeção durante o corte", "hint": "Verificar aperto do mordente com a peça típica utilizada — folga aqui é causa comum de projeção de material."}, {"id": "C.4", "text": "Travão da lâmina/disco funcional — imobiliza rapidamente após comando de paragem", "hint": "Testar tempo de paragem após desligar — uma lâmina que continua a rodar por vários segundos aumenta o risco em qualquer intervenção seguinte."}, {"id": "C.5", "text": "Sistema de extração de aparas/limalha funcional, quando aplicável", "hint": "Verificar se a extração está ligada e sem obstruções visíveis."}, {"id": "C.6", "text": "Sistema de refrigeração/lubrificação de corte sem fugas; FDS do fluido de corte disponível", "hint": "Inspecionar mangueiras e bocais de refrigerante. Verificar código LER correto para o fluido de corte usado nos registos de resíduos."}, {"id": "C.7", "text": "Zona de avanço/saída automática do material sem acesso do operador durante o ciclo", "hint": "Aplicável a serras de tubo com avanço automático — verificar proteção ao longo de todo o percurso de avanço."}, {"id": "C.8", "text": "Botão de emergência acessível ao operador", "hint": "Confirmar alcance sem deslocação e funcionamento efetivo."}, {"id": "C.9", "text": "Pedal de comando (se existente) protegido contra acionamento acidental", "hint": "Verificar chapéu/protetor metálico e estado do cabo do pedal."}]}], "note": "Este módulo insere-se no \"Checklist de Segurança de Equipamentos de Trabalho — Núcleo Geral IETA\", entre a Secção A e a Secção E, sempre que o equipamento em avaliação for uma máquina de corte. Está dividido em duas subsecções pela natureza do risco: B (radiação laser, gases de assistência, fumos de corte) e C (órgãos de corte mecânico — lâmina/disco, fixação da peça). Aplicar apenas a subsecção correspondente ao equipamento em avaliação. Nota: os limites de exposição a fumos de corte e a periodicidade de manutenção dos filtros de extração devem ser confirmados junto do fabricante do equipamen", "standalone": false, "multi": true}, {"id": "soldadura", "name": "Soldadura", "sections": [{"id": "B", "title": "B — SOLDADURA POR PONTOS (resistência)", "items": [{"id": "B.1", "text": "Elétrodos e braços da pinça sem desgaste excessivo; força de aperto regulada corretamente", "hint": "Verificar estado da ponta dos elétrodos (desgaste/deformação) e se a força de aperto está conforme especificação para a espessura de chapa soldada."}, {"id": "B.2", "text": "Zona de aperto protegida — resguardo com interlocking (pinças estacionárias) ou distância de segurança das mãos ao ponto de soldadura (pinças manuais suspensas)", "hint": "Em pinças estacionárias/robotizadas, testar o interlocking do resguardo. Em pinças manuais, verificar se o desenho da pinça mantém as mãos do operador afastadas do ponto de aperto."}, {"id": "B.3", "text": "Sistema de refrigeração por água sem fugas; circuito e torre de arrefecimento (quando existente) em bom estado", "hint": "Verificar mangueiras de água nos elétrodos e no transformador — fugas aqui são frequentes e passam despercebidas até causar avaria elétrica."}, {"id": "B.4", "text": "Comando bimanual ou pedal com proteção contra acionamento acidental (pinças estacionárias)", "hint": "Testar comando bimanual — deve exigir as duas mãos em simultâneo. Se pedal, verificar chapéu/protetor."}, {"id": "B.5", "text": "Paragem de emergência acessível — corta a corrente de soldadura e o movimento dos elétrodos", "hint": "Testar durante um ciclo de soldadura."}, {"id": "B.6", "text": "Cabos e transformador sem danos visíveis; ligação à terra da estrutura verificada", "hint": "Inspecionar isolamento dos cabos secundários (correntes elevadas) e ligação à terra da carcaça do equipamento."}, {"id": "B.7", "text": "Proteção contra projeção de partículas incandescentes (écran/resguardo) na zona de trabalho", "hint": "A soldadura por pontos projeta salpicos de metal fundido — verificar existência de anteparo entre o ponto de soldadura e zonas de circulação/outros postos."}, {"id": "B.8", "text": "Célula robotizada de soldadura por pontos: perímetro vedado com cortina de luz ou resguardo interbloqueado, testado", "hint": "Testar interrupção do ciclo ao violar o perímetro (cortina de luz) ou ao abrir o resguardo durante o funcionamento."}]}, {"id": "C", "title": "C — SOLDADURA POR ARCO (MIG/MAG/TIG/elétrodo revestido)", "items": [{"id": "C.1", "text": "Cabos de soldadura sem danos no isolamento; uniões e conectores em bom estado", "hint": "Inspecionar todo o comprimento do cabo, sobretudo junto à pinça porta-elétrodos/tocha e junto ao equipamento."}, {"id": "C.2", "text": "Tensão em vazio dentro dos limites de segurança do equipamento; pinça porta-elétrodos/tocha isolada e sem danos", "hint": "Verificar isolamento do punho da pinça/tocha e ausência de partes metálicas expostas ao alcance da mão."}, {"id": "C.3", "text": "Garrafas de gás de proteção (árgon, CO2, misturas) fixadas verticalmente com corrente/suporte; identificação do gás visível", "hint": "Garrafa não fixada é risco de queda/projeção em caso de rutura da válvula. Confirmar identificação clara do conteúdo."}, {"id": "C.4", "text": "Redutor de pressão e mangueiras de gás sem fugas", "hint": "Verificar uniões e estado geral das mangueiras de gás de proteção."}, {"id": "C.5", "text": "Sistema/local de extração de fumos de soldadura funcional e posicionado corretamente junto ao ponto de trabalho", "hint": "Confirmar que a extração está a captar o fumo na origem e não apenas a diluir no ambiente geral."}, {"id": "C.6", "text": "Biombos/anteparos de proteção contra radiação do arco, protegendo terceiros e postos de trabalho vizinhos", "hint": "A radiação UV/IV do arco pode afetar olhos e pele de trabalhadores próximos que não estão a soldar — verificar se há separação visual adequada."}, {"id": "C.7", "text": "EPI específico disponível e em bom estado: máscara com filtro adequado ao processo, avental/mangas de proteção, luvas, proteção auditiva quando aplicável", "hint": "Confirmar o grau de proteção do filtro da máscara é adequado ao processo e corrente utilizados."}, {"id": "C.8", "text": "Ligação à terra da peça/bancada de trabalho confirmada antes do início da soldadura", "hint": "Sem retorno de terra correto, a corrente pode procurar caminhos alternativos através de outras estruturas metálicas."}, {"id": "C.9", "text": "Extintor adequado disponível próximo, dado o risco de faíscas/salpicos junto a materiais inflamáveis", "hint": "Verificar proximidade e validade, sobretudo se houver armazenamento de materiais combustíveis nas proximidades do posto."}, {"id": "C.10", "text": "Ventilação geral da zona de trabalho adequada, complementar à extração localizada", "hint": "Fumos de soldadura contêm partículas metálicas finas e, consoante o material base/revestimento, gases nocivos — avaliar renovação de ar do espaço."}]}], "note": "Este módulo insere-se no \"Checklist de Segurança de Equipamentos de Trabalho — Núcleo Geral IETA\", entre a Secção A e a Secção E, sempre que o equipamento em avaliação for uma máquina de soldar. Está dividido em duas subsecções pela natureza do risco: B (soldadura por pontos — esmagamento, campos elétricos/térmicos localizados) e C (soldadura por arco — radiação, fumos, gases de proteção). Aplicar apenas a subsecção correspondente ao equipamento em avaliação; postos com os dois processos preenchem ambas. Nota: a série EN 60974 (equipamento de soldadura por arco) é a referência habitual de proj", "standalone": false, "multi": true}, {"id": "acabamento", "name": "Acabamento de Superfície", "sections": [{"id": "B", "title": "B — REBARBADORAS E BURILOS (rebolos/discos abrasivos)", "items": [{"id": "B.1", "text": "Resguardo do disco/rebolo cobrindo a parte não utilizada no trabalho", "hint": "Verificar se o resguardo expõe apenas o mínimo de disco necessário à tarefa; ajuste do resguardo deslizante em rebarbadoras portáteis."}, {"id": "B.2", "text": "Disco/rebolo com velocidade máxima marcada compatível com a velocidade de rotação da máquina", "hint": "Confirmar que a velocidade máxima gravada no disco é igual ou superior à velocidade da máquina — usar disco de velocidade inferior à da máquina é risco de rutura."}, {"id": "B.3", "text": "Disco/rebolo sem fissuras, lascas ou deformação; dentro do prazo de validade (quando aplicável) antes de ser montado", "hint": "Inspecionar visualmente e, se possível, fazer o \"teste do som\" (bater levemente e ouvir se o som é limpo, não abafado/rachado) antes de montar."}, {"id": "B.4", "text": "Flanges de fixação corretos para o disco utilizado; disco centrado, sem vibração excessiva ao arrancar", "hint": "Verificar se as flanges são as previstas pelo fabricante da máquina/disco e se o aperto está correto."}, {"id": "B.5", "text": "Esmeril/burilo de bancada: apoio de peça (tool rest) ajustado a distância mínima do disco", "hint": "Distância excessiva entre o apoio e o disco permite que a peça seja puxada para dentro — verificar e reajustar se necessário."}, {"id": "B.6", "text": "Esmeril/burilo de bancada: écran de proteção transparente (viseira) presente, além do EPI individual", "hint": "Verificar se o écran está intacto, transparente e corretamente posicionado à frente do disco."}, {"id": "B.7", "text": "Sistema de extração de poeiras/partículas, quando existente, funcional", "hint": "Aplicável sobretudo a postos fixos de rebarbagem com extração dedicada."}, {"id": "B.8", "text": "EPI disponível e adequado: óculos ou viseira, proteção auditiva, luvas que não fiquem presas ao disco em rotação", "hint": "Luvas de tecido muito folgadas podem ser um risco adicional junto a discos em rotação — confirmar tipo de luva adequado à tarefa."}, {"id": "B.9", "text": "Rebarbadoras portáteis: cabo elétrico e ficha em bom estado; interruptor de \"homem morto\" (deadman) funcional", "hint": "Testar se o disco para assim que se larga o gatilho/interruptor."}, {"id": "B.10", "text": "Exposição a vibração mão-braço avaliada ou conhecida, para uso prolongado de rebarbadoras portáteis", "hint": "Relevante para gestão de tempos de exposição em postos com uso intensivo — a confirmar se existe avaliação realizada."}]}, {"id": "C", "title": "C — ROTOFINISH (máquinas vibratórias de polimento/rebarbagem)", "items": [{"id": "C.1", "text": "Tampa/resguardo da cuba vibratória com interlocking — a máquina não funciona com a tampa aberta", "hint": "Testar: abrir a tampa durante o funcionamento deve parar a vibração de imediato."}, {"id": "C.2", "text": "Estrutura de suporte e amortecedores de vibração em bom estado, sem fissuras, folgas ou desalinhamento", "hint": "Verificar apoios elásticos/molas de suspensão da cuba — desgaste aqui aumenta a vibração transmitida à estrutura do edifício."}, {"id": "C.3", "text": "Sistema de separação de peças/meios abrasivos (crivo, vibrador separador) protegido, sem acesso a partes móveis", "hint": "Verificar se a zona de separação tem resguardo e se o acesso para desobstrução exige paragem da máquina."}, {"id": "C.4", "text": "Nível de ruído da máquina avaliado ou conhecido", "hint": "Máquinas vibratórias de rebarbagem/polimento são fonte significativa e contínua de ruído — confirmar se há avaliação de ruído do posto."}, {"id": "C.5", "text": "Contenção adequada quando o processo é a húmido — sem derrame de líquido/composto para o pavimento envolvente", "hint": "Verificar vedação da cuba e escoamento controlado do líquido de processo, quando aplicável."}, {"id": "C.6", "text": "FDS do composto/meio de polimento (quando líquido ou químico) disponível", "hint": "Confirmar acessibilidade da FDS e código LER correto para o resíduo gerado (lamas, água de processo)."}, {"id": "C.7", "text": "EPI disponível: proteção auditiva, luvas resistentes a químicos (processo a húmido), óculos", "hint": "Confirmar adequação das luvas ao composto usado, não apenas proteção mecânica genérica."}, {"id": "C.8", "text": "Paragem de emergência acessível", "hint": "Testar acionamento e confirmar paragem efetiva da vibração."}, {"id": "C.9", "text": "Ligação à terra e cablagem elétrica em bom estado, considerando ambiente frequentemente húmido", "hint": "Ambientes húmidos exigem atenção redobrada ao estado do isolamento e das ligações elétricas — verificar grau de proteção IP do equipamento."}]}], "note": "Este módulo insere-se no \"Checklist de Segurança de Equipamentos de Trabalho — Núcleo Geral IETA\", entre a Secção A e a Secção E, sempre que o equipamento em avaliação for uma máquina de acabamento por abrasão ou vibração. Está dividido em duas subsecções: B (rebarbadoras portáteis e esmeris/burilos de bancada — risco de rutura de disco e projeção) e C (rotofinish — enclausuramento, separação de meios e ruído). A tina de decapagem não está incluída aqui por ser predominantemente risco químico/de instalação — será tratada em documento próprio. Nota: a EN 12413 (rebolos e discos abrasivos aglome", "standalone": false, "multi": true}, {"id": "decapagem", "name": "Tina de Decapagem", "sections": [{"id": "A", "title": "A — IDENTIFICAÇÃO E FDS", "items": [{"id": "A.1", "text": "FDS do(s) produto(s) da tina de decapagem atualizada (conforme REACH/CLP) e disponível junto ao posto, em português", "hint": "Confirmar data da última revisão da FDS junto do fornecedor. FDS desatualizada é uma NC de documentação frequente."}, {"id": "A.2", "text": "Rotulagem da tina/recipiente conforme Regulamento CLP — pictogramas de perigo e frases H/P visíveis", "hint": "Verificar se a tina tem identificação do produto e pictogramas de perigo afixados, não apenas o rótulo original do bidão de origem."}, {"id": "A.3", "text": "FDS dos produtos auxiliares (neutralização, enxaguamento, tratamento do banho), quando existentes, também disponível", "hint": "Aplicável se houver etapas de neutralização ou tratamento associadas ao processo."}]}, {"id": "B", "title": "B — CONTENÇÃO E INSTALAÇÃO", "items": [{"id": "B.1", "text": "Bacia de retenção/contenção secundária dimensionada para o volume total da tina", "hint": "Em caso de rutura da tina, a bacia deve conseguir reter o volume do banho sem transbordar para o pavimento geral."}, {"id": "B.2", "text": "Tina sem fissuras, corrosão visível ou fugas no revestimento interno", "hint": "Inspecionar paredes exteriores e base da tina, e o estado do revestimento interior resistente ao produto."}, {"id": "B.3", "text": "Sistema de extração de vapores/gases funcional, com captação junto à superfície do banho", "hint": "Confirmar que a extração está a funcionar e posicionada para captar os vapores na origem, não apenas a diluir no ambiente."}, {"id": "B.4", "text": "Ventilação geral do espaço complementar à extração localizada", "hint": "Avaliar renovação de ar da zona envolvente à tina, sobretudo em espaços fechados ou pouco ventilados."}]}, {"id": "C", "title": "C — PROTEÇÃO DO TRABALHADOR", "items": [{"id": "C.1", "text": "EPI específico disponível: óculos/viseira química, luvas resistentes ao produto, avental ou fato impermeável, calçado resistente a químicos", "hint": "Confirmar na FDS o tipo de luva/material recomendado para este produto em concreto — nem toda a luva de proteção química serve para todos os produtos."}, {"id": "C.2", "text": "Duche de emergência e lava-olhos acessíveis a curta distância do posto, funcionais e testados periodicamente", "hint": "O percurso até ao duche/lava-olhos deve ser rápido e desobstruído. Confirmar registo do último teste de funcionamento."}, {"id": "C.3", "text": "Sinalização de perigo químico e obrigatoriedade de EPI afixada junto à tina", "hint": "Verificar presença e legibilidade da sinalização normalizada."}, {"id": "C.4", "text": "Procedimento escrito para carregamento/descarregamento de peças na tina, minimizando salpicos e risco de mergulho de mãos/braços", "hint": "Confirmar se existe instrução clara sobre uso de cestos, ganchos ou suportes, em vez de manuseamento direto das peças no banho."}, {"id": "C.5", "text": "Procedimento de emergência em caso de contacto com pele/olhos ou derrame, afixado e conhecido pelos operadores", "hint": "Perguntar diretamente a um operador o que faria em caso de salpico nos olhos — resposta insegura ou hesitante é sinal de falha de formação, mesmo que o procedimento esteja afixado."}]}, {"id": "D", "title": "D — GESTÃO DE RESÍDUOS E DERRAMES", "items": [{"id": "D.1", "text": "Kit de contenção de derrames (absorvente adequado ao produto) disponível junto à tina", "hint": "Confirmar que o absorvente é compatível com o produto (ácido/base/outro) e não apenas um kit genérico."}, {"id": "D.2", "text": "Código LER correto atribuído ao efluente/lamas gerados pelo processo de decapagem", "hint": "O código deve refletir o processo gerador (tratamento de superfície) e não apenas a aparência do resíduo — mesma lógica já aplicada a outros resíduos da IETA."}, {"id": "D.3", "text": "Procedimento definido para neutralização e descarte do banho em fim de vida", "hint": "Confirmar se existe destino definido (operador licenciado) e se o processo de neutralização, quando aplicável, está documentado."}, {"id": "D.4", "text": "Registo de substituição do banho disponível (datas, quantidade retirada, destino)", "hint": "A ausência de registo dificulta o rastreio da gestão do produto perigoso ao longo do tempo."}]}, {"id": "E", "title": "E — FORMAÇÃO E VIGILÂNCIA DA SAÚDE", "items": [{"id": "E.1", "text": "Operadores com formação específica sobre os riscos do produto e os procedimentos de emergência associados", "hint": "Confirmar registo de formação — não assumir que a experiência prática substitui a formação formal sobre riscos químicos."}, {"id": "E.2", "text": "Vigilância da saúde do(s) operador(es) contempla a exposição a este produto/processo", "hint": "Confirmar junto da medicina do trabalho se a ficha de aptidão do posto reflete este risco específico."}]}], "note": "Nota: a periodicidade formal de teste dos duches de emergência/lava-olhos (C.2) e eventuais requisitos legais específicos de armazenamento de produtos corrosivos não foram citados com norma/artigo concreto por não terem sido ainda confirmados — a validar antes de constarem no relatório final.", "standalone": true, "multi": false}, {"id": "embalagem", "name": "Embalagem", "sections": [{"id": "B", "title": "B — CINTADORA DE PALETES", "items": [{"id": "B.1", "text": "Zona de tensionamento/corte da cinta com resguardo, sem acesso direto durante o ciclo", "hint": "Verificar se o mecanismo de tensionamento e a lâmina/dispositivo de corte da cinta estão protegidos de contacto acidental."}, {"id": "B.2", "text": "Sistema de corte automático da cinta protegido — sem acesso à lâmina/mecanismo durante a operação", "hint": "Testar um ciclo completo e observar se existe qualquer ponto de acesso à zona de corte sem abrir um resguardo."}, {"id": "B.3", "text": "Sensor/interlocking impede o arranque com acesso aberto à zona de cintagem, quando existente", "hint": "Aplicável a cintadoras automáticas com cabine ou porta de acesso — testar interrupção do ciclo ao abrir."}, {"id": "B.4", "text": "Bobine de cinta fixa corretamente no suporte, sem risco de queda durante a rotação/alimentação", "hint": "Verificar fixação do eixo/suporte da bobine."}, {"id": "B.5", "text": "Cintadoras térmicas (solda a cinta por calor): superfície/resistência quente sinalizada ou protegida", "hint": "Aplicável apenas a cintadoras com solda térmica da cinta — verificar acessibilidade da zona quente durante e após o ciclo."}, {"id": "B.6", "text": "Botão de emergência acessível ao operador", "hint": "Testar alcance e funcionamento efetivo — deve parar o tensionamento e o corte de imediato."}, {"id": "B.7", "text": "Cabo elétrico e ficha em bom estado; ligação à terra da estrutura verificada", "hint": "Inspecionar isolamento do cabo, sobretudo em equipamentos móveis/semiautomáticos que são deslocados com frequência."}]}, {"id": "C", "title": "C — ENVOLVEDORA DE PALETES (plataforma giratória)", "items": [{"id": "C.1", "text": "Plataforma giratória com resguardo perimetral ou sinalização clara da zona de perigo durante a rotação", "hint": "Verificar se a zona de rotação da plataforma está sinalizada no pavimento e, idealmente, fisicamente delimitada."}, {"id": "C.2", "text": "Sensor de presença ou dispositivo de paragem automática caso alguém entre na zona de rotação, quando existente", "hint": "Aplicável a equipamentos com deteção de presença — testar se disponível."}, {"id": "C.3", "text": "Botão de emergência acessível, interrompe simultaneamente a rotação da plataforma e o movimento do mastro/braço", "hint": "Testar durante um ciclo — deve parar ambos os movimentos, não apenas um."}, {"id": "C.4", "text": "Sistema de elevação do rolo de filme (mastro) sem folgas; cabo/corrente de elevação sem defeitos visíveis", "hint": "Inspecionar o mastro ao longo de um ciclo completo de subida/descida."}, {"id": "C.5", "text": "Zona de carregamento/remoção da palete sem obstruções e com espaço de manobra adequado", "hint": "Verificar se o empilhador/porta-paletes consegue aceder e sair sem manobras forçadas."}, {"id": "C.6", "text": "Velocidade de rotação adequada à estabilidade da carga, sem risco de projeção ou queda de material da palete", "hint": "Avaliar com o tipo de carga habitual — paletes instáveis ou mal paletizadas agravam este risco independentemente da máquina."}, {"id": "C.7", "text": "Sinalização de perigo (esmagamento/entalamento na zona de rotação) afixada", "hint": "Confirmar presença e legibilidade da sinalização junto ao equipamento."}]}], "note": "Este módulo insere-se no \"Checklist de Segurança de Equipamentos de Trabalho — Núcleo Geral IETA\", entre a Secção A e a Secção E, sempre que o equipamento em avaliação for uma máquina de cintar ou envolver paletes. Está dividido em duas subsecções: B (cintadora — tensionamento e corte da cinta) e C (envolvedora — rotação da plataforma e elevação do rolo de filme).", "standalone": false, "multi": true}, {"id": "compressores", "name": "Compressores", "sections": [{"id": "B", "title": "B — COMPRESSOR DE AR", "items": [{"id": "B.1", "text": "Reservatório de ar sob pressão com placa de identificação (pressão máxima admissível, volume, ano de fabrico)", "hint": "Verificar se a placa está presente e legível no depósito de ar."}, {"id": "B.2", "text": "Válvula de segurança (alívio de pressão) presente, com prazo/selo de verificação dentro da validade", "hint": "Confirmar existência da válvula de segurança calibrada para a pressão máxima admissível do depósito e registo da última verificação."}, {"id": "B.3", "text": "Manómetro funcional e legível", "hint": "Verificar leitura coerente com o funcionamento e ausência de danos no mostrador/vidro."}, {"id": "B.4", "text": "Purga de condensados funcional (manual ou automática)", "hint": "Confirmar drenagem regular do depósito — acumulação de água favorece corrosão interna e reduz a vida útil do reservatório."}, {"id": "B.5", "text": "Registo de inspeção periódica do equipamento sob pressão disponível", "hint": "Equipamentos sob pressão estão sujeitos a legislação e periodicidade de inspeção próprias — confirmar com a entidade responsável qual a periodicidade e o regime aplicável a este reservatório em concreto."}, {"id": "B.6", "text": "Resguardo de correias/polias (compressores de pistão com transmissão por correia)", "hint": "Verificar cobertura da transmissão, análoga ao critério usado noutras máquinas com transmissão por correia."}, {"id": "B.7", "text": "Ligação elétrica e ligação à terra verificadas", "hint": "Inspecionar cabo de alimentação e ligação à terra da carcaça/estrutura."}, {"id": "B.8", "text": "Nível de ruído do compressor avaliado ou conhecido; isolamento acústico ou compartimento dedicado, quando aplicável", "hint": "Compressores são frequentemente uma fonte de ruído contínuo relevante — confirmar se existe avaliação do posto/zona envolvente."}, {"id": "B.9", "text": "Ventilação adequada da sala/zona do compressor, permitindo dissipação do calor gerado", "hint": "Verificar temperatura ambiente da zona e existência de entradas de ar/extração, sobretudo em compartimentos fechados."}, {"id": "B.10", "text": "Filtros de ar/óleo em bom estado; sem fugas de óleo ou ar visíveis nas uniões", "hint": "Inspecionar mangueiras, uniões roscadas e estado geral de limpeza em torno do compressor."}, {"id": "B.11", "text": "Botão de paragem de emergência acessível, em compressores de maior potência", "hint": "Aplicável sobretudo a compressores industriais de maior dimensão/potência."}]}], "note": "Este módulo insere-se no \"Checklist de Segurança de Equipamentos de Trabalho — Núcleo Geral IETA\", entre a Secção A e a Secção E, sempre que o equipamento em avaliação for um compressor de ar com reservatório sob pressão. Nota: o compressor é simultaneamente um equipamento de trabalho (DL 50/2005) e um equipamento sob pressão, com regime de inspeção periódica próprio. O ponto B.5 exige confirmação da periodicidade e entidade responsável aplicável — não foi assumido nenhum valor por não haver, neste momento, confirmação documental suficiente. Nota: a legislação nacional específica de equipament", "standalone": false, "multi": false}, {"id": "forno", "name": "Forno Industrial", "sections": [{"id": "B", "title": "B — FORNO (secagem/cura/tratamento térmico)", "items": [{"id": "B.1", "text": "Porta do forno com fecho seguro; interbloqueio impede aquecimento com a porta aberta, quando aplicável", "hint": "Testar, se existir interlocking, se o aquecimento é interrompido ao abrir a porta durante o ciclo."}, {"id": "B.2", "text": "Isolamento térmico da estrutura em bom estado; superfícies exteriores sem pontos de temperatura excessiva ao toque", "hint": "Percorrer as superfícies exteriores acessíveis ao trabalhador e identificar zonas de temperatura anormalmente elevada (isolamento degradado)."}, {"id": "B.3", "text": "Sistema de controlo de temperatura funcional, com limitador/termóstato de segurança independente do controlo principal", "hint": "Confirmar existência de um segundo dispositivo de corte por sobretemperatura, independente do controlador normal de processo."}, {"id": "B.4", "text": "Sistema de extração de fumos/vapores de processo funcional", "hint": "Verificar caudal e estado da extração — relevante sobretudo em fornos de cura/secagem de produtos com solventes."}, {"id": "B.5", "text": "Aquecimento a gás: deteção de fuga de gás, válvula de corte automática e pré-ventilação antes do arranque", "hint": "Aplicável apenas a fornos com queimador a gás — confirmar existência destes dispositivos de segurança específicos da combustão."}, {"id": "B.6", "text": "Atmosfera com solventes/COV (fornos de cura de tinta): classificação ATEX da zona e equipamento elétrico interior adequado", "hint": "Aplicável a fornos de cura associados a processos de pintura — confirmar se a zona interior foi classificada e se o equipamento elétrico instalado é certificado para essa zona."}, {"id": "B.7", "text": "Paragem de emergência acessível, corta a fonte de calor", "hint": "Testar acionamento e confirmar corte efetivo da fonte de energia térmica (resistências/queimador)."}, {"id": "B.8", "text": "Extintor adequado disponível próximo, dado o risco térmico/incêndio associado", "hint": "Verificar proximidade, validade e adequação do extintor ao tipo de risco (elétrico/químico)."}, {"id": "B.9", "text": "Sinalização de superfície quente e proibição de acesso durante o funcionamento", "hint": "Confirmar presença e legibilidade da sinalização junto às zonas de maior risco."}, {"id": "B.10", "text": "Registo de manutenção/calibração dos controlos e limitadores de temperatura disponível", "hint": "A ausência de registo de calibração do limitador de segurança é uma NC relevante, dado o seu papel de última barreira contra sobreaquecimento."}]}], "note": "Este módulo insere-se no \"Checklist de Segurança de Equipamentos de Trabalho — Núcleo Geral IETA\", entre a Secção A e a Secção E, sempre que o equipamento em avaliação for um forno industrial. Os pontos B.5 e B.6 são condicionais à fonte de energia e ao processo — aplicar apenas os relevantes ao forno concreto e marcar os restantes como NA. Nota: requisitos específicos de segurança de queimadores a gás e classificação formal de zona ATEX devem ser confirmados com o fabricante/projetista do forno antes de constarem no relatório final.", "standalone": false, "multi": false}, {"id": "pintura", "name": "Cabine de Pintura", "sections": [{"id": "B", "title": "B — CABINE DE PINTURA", "items": [{"id": "B.1", "text": "Sistema de extração/ventilação forçada funcional, com caudal adequado e filtros de exaustão em bom estado", "hint": "Confirmar plano de substituição dos filtros — filtros saturados reduzem o caudal e aumentam a concentração de vapores/partículas no interior."}, {"id": "B.2", "text": "Interbloqueio entre o sistema de extração e o equipamento de pintura — não é possível pintar sem a extração ligada", "hint": "Testar se a pistola/equipamento fica bloqueado ou sinalizado quando a extração está desligada ou insuficiente."}, {"id": "B.3", "text": "Classificação da zona (interior da cabine e envolvente) e equipamento elétrico interior certificado para atmosferas potencialmente explosivas", "hint": "Confirmar se existe classificação de zona ATEX formal e se as luminárias, motores e outros equipamentos elétricos no interior são certificados para essa zona."}, {"id": "B.4", "text": "Iluminação interior da cabine adequada à classificação ATEX aplicável", "hint": "Aplicável em conjunto com B.3 — luminárias não certificadas em zona classificada são NC crítica."}, {"id": "B.5", "text": "Ligação à terra da cabine, das peças a pintar e do pavimento/calçado do operador, evitando acumulação de carga eletrostática", "hint": "A descarga eletrostática é uma fonte de ignição relevante em ambiente com vapores de solvente — confirmar continuidade elétrica até à terra."}, {"id": "B.6", "text": "Ausência de fontes de ignição na cabine e zona envolvente; trabalhos a quente sujeitos a autorização/permissão de trabalho", "hint": "Verificar se existe procedimento de permissão de trabalho a quente (soldadura, corte, esmerilagem) nas proximidades da cabine."}, {"id": "B.7", "text": "Armazenamento de tintas/solventes na cabine limitado ao estritamente necessário ao turno; armazém principal separado e ventilado", "hint": "Grandes quantidades de tinta/solvente dentro ou junto à cabine aumentam desnecessariamente a carga de incêndio do espaço."}, {"id": "B.8", "text": "EPI específico disponível: proteção respiratória adequada ao produto (máscara com filtro ou linha de ar, conforme avaliação), luvas, fato de proteção", "hint": "Confirmar na FDS o tipo de proteção respiratória recomendada para os produtos efetivamente utilizados."}, {"id": "B.9", "text": "FDS das tintas, solventes e vernizes utilizados disponível junto ao posto", "hint": "Verificar acessibilidade e atualização das fichas de dados de segurança."}, {"id": "B.10", "text": "Extintor adequado e sistema de deteção/combate a incêndio (quando existente) operacional", "hint": "Confirmar validade do extintor e, se houver sistema fixo de deteção/supressão, registo da última verificação."}, {"id": "B.11", "text": "Gestão de resíduos de pintura (panos, filtros, embalagens vazias) com código LER correto e armazenamento adequado", "hint": "Panos e filtros contaminados com solvente/tinta são frequentemente resíduos perigosos — confirmar acondicionamento e código LER."}, {"id": "B.12", "text": "Paragem de emergência acessível", "hint": "Testar acionamento e confirmar corte efetivo da fonte de energia/alimentação de produto."}]}], "note": "Este módulo insere-se no \"Checklist de Segurança de Equipamentos de Trabalho — Núcleo Geral IETA\", entre a Secção A e a Secção E, sempre que o equipamento em avaliação for uma cabine de pintura. O risco dominante é de atmosfera potencialmente explosiva (vapores de solvente) associado a fontes de ignição — os pontos ATEX (B.3/B.4) são prioritários. Nota: a classificação formal de zonas ATEX da cabine (documento de proteção contra explosões) deve ser confirmada com o projetista/fabricante — não foi assumida neste checklist por não haver, neste momento, confirmação documental.", "standalone": false, "multi": false}], "core": {"pre": [{"id": "A", "title": "A — REQUISITOS GERAIS (DL 50/2005, Anexo I)", "items": [{"id": "A.1", "text": "Sistemas de comando — identificação clara em PT ou simbologia normalizada; posições de funcionamento visíveis", "hint": "Verificar cada botão/seletor: tem etiqueta legível (ex: LIGA/DESLIGA, SUBIDA/DESCIDA)? Botões desgastados sem legenda = NC. Simbologia ISO 7000 é aceite como alternativa a texto."}, {"id": "A.2", "text": "Arranque do equipamento — exige ação intencional; sem arranque acidental por reposição de energia", "hint": "Testar: retirar e repor alimentação (elétrica/pneumática/hidráulica) — o equipamento não pode arrancar sozinho. Verificar se existe função de re-arranque automático após falha de energia."}, {"id": "A.3", "text": "Paragem normal — dispositivo acessível e funcional; paragem prioritária ao arranque", "hint": "Identificar o comando de paragem principal. Testar durante o funcionamento — deve ter prioridade sobre qualquer comando de arranque simultâneo."}, {"id": "A.4", "text": "Paragem de emergência — botão vermelho/fundo amarelo acessível ao operador; retorno manual após atuação (EN ISO 13850)", "hint": "Existe botão de emergência (cogumelo vermelho, fundo amarelo)? Está ao alcance do operador sem deslocação? Após acionado, o equipamento não pode reiniciar sem desbloqueio manual + ação intencional de reset."}, {"id": "A.5", "text": "Estabilidade — fixação/ancoragem adequada ao pavimento ou estrutura; sem oscilação ou deslocamento anormal durante o funcionamento", "hint": "Verificar parafusos/chumbadouros/calços de fixação sem folga visível. Para equipamentos móveis (empilhadores, stackers, porta-paletes), avaliar estabilidade em carga e em piso inclinado, conforme aplicável."}, {"id": "A.6", "text": "Estrutura — chassis, estrutura de suporte, colunas, mastros ou braços sem fissuras, deformações ou corrosão estrutural visível", "hint": "Inspecionar visualmente os elementos estruturais principais (variam por tipo de equipamento — ver módulo técnico). Atenção a pontos de solda estrutural e zonas de maior esforço."}, {"id": "A.7", "text": "Projeções — proteção contra projeção de material, peças, aparas, faíscas ou salpicos de fluidos", "hint": "Identificar o(s) ponto(s) de projeção previsível (corte, rebarbagem, soldadura, prensagem, aparas de maquinação) e verificar existência de resguardo, anteparo ou defletor adequado."}, {"id": "A.8", "text": "Emanações / fugas — inexistência de fugas visíveis de óleo, fluido hidráulico, ar comprimido ou outros fluidos de processo", "hint": "Inspecionar o pavimento sob o equipamento e ao longo do percurso de mangueiras/tubagens/uniões. Registar localização exata de qualquer fuga."}, {"id": "A.9", "text": "Riscos de contacto mecânico — zona(s) de perigo (corte, esmagamento, arrasto, rotação) protegida(s) por resguardo com interlocking ou dispositivo equivalente", "hint": "Identificar a(s) zona(s) de perigo do equipamento. Verificar o dispositivo de proteção existente: resguardo fixo, resguardo móvel interbloqueado, cortina de luz, comando bimanual ou distância de segurança — ver módulo técnico específico para o critério aplicável."}, {"id": "A.10", "text": "Iluminação — zona de trabalho com iluminação suficiente; sem sombras na zona operativa", "hint": "Avaliar se o operador consegue ver claramente a zona de trabalho/peça com a iluminação existente. Existe luminária dedicada ou depende só da iluminação geral da nave?"}, {"id": "A.11", "text": "Temperatura — superfícies quentes (motores, sistemas hidráulicos, fornos, zonas de soldadura/corte/atrito) protegidas ou sinalizadas", "hint": "Verificar se as superfícies que atingem temperatura elevada durante o funcionamento estão acessíveis ao toque involuntário e se têm sinalização adequada."}, {"id": "A.12", "text": "Dispositivos de alerta — sinalização de arranque e avisos de perigo visíveis e legíveis", "hint": "Existe sinal sonoro ou luminoso de arranque (quando aplicável)? Avisos colados/pintados ainda legíveis? Sinalização de EPI obrigatório presente?"}, {"id": "A.13", "text": "Manutenção — pontos de intervenção acessíveis com equipamento parado; procedimento LOTO implementado", "hint": "Existe procedimento escrito de LOTO afixado? Existe cadeado disponível para bloquear a fonte de energia? Os pontos de lubrificação/manutenção são acessíveis sem entrar em zona de perigo?"}, {"id": "A.14", "text": "Riscos elétricos — quadro elétrico identificado; cablagem sem danos; ligação à terra verificada", "hint": "Quadro com sinal de perigo elétrico? Porta fecha sem danos? Cabos visíveis sem fissuras no isolamento, sem contacto com óleo ou superfícies quentes. Ligação à terra na carcaça do motor/estrutura."}, {"id": "A.15", "text": "Riscos de incêndio — sem fontes de ignição próximas de materiais ou fluidos inflamáveis", "hint": "Verificar proximidade de trabalhos de soldadura/corte a materiais inflamáveis, armazenamento de fluidos inflamáveis junto ao equipamento, e disponibilidade de extintor adequado nas proximidades."}, {"id": "A.16", "text": "Riscos de explosão", "hint": "Aplicável apenas a equipamentos/processos com atmosferas potencialmente explosivas (ex: cabines de pintura, zonas ATEX). Marcar NA quando não aplicável."}, {"id": "A.17", "text": "Fontes de energia — corte geral com possibilidade de bloqueio na posição desligado (LOTO)", "hint": "Localizar o interruptor/válvula geral de cada fonte de energia do equipamento. Verificar previsão de bloqueio por cadeado."}, {"id": "A.18", "text": "Sinalização de segurança — sinais de EPI, zonas de perigo e instruções básicas visíveis", "hint": "Verificar presença e legibilidade: EPI obrigatório, proibição de acesso durante funcionamento, instruções básicas de operação. Sinais desbotados ou em falta = NC."}]}], "post": [{"id": "E", "title": "E — FONTES DE ENERGIA E LOTO (Pontos 7 e 8 do DL 50/2005, Anexo I)", "items": [{"id": "E.1", "text": "Corte geral da energia elétrica com possibilidade de bloqueio (cadeado) na posição desligado", "hint": "Localizar o disjuntor/interruptor geral. Verificar orifício para cadeado ou previsão de bloqueador. Solução simples se não existir: bloqueador de disjuntor universal (~5–15€)."}, {"id": "E.2", "text": "Corte geral de outras fontes de energia do equipamento (hidráulica, pneumática, mecânica armazenada) com bloqueio na posição desligado, conforme aplicável", "hint": "Identificar todas as fontes de energia do equipamento além da elétrica (ver módulo técnico). Verificar existência de válvula/dispositivo de corte com possibilidade de bloqueio."}, {"id": "E.3", "text": "Procedimento LOTO documentado em português e afixado junto ao equipamento", "hint": "Instrução escrita passo-a-passo: parar, isolar cada fonte de energia, bloquear, dissipar energia residual, verificar ausência de energia antes de intervir. Se não existir = NC, pode ser elaborado internamente."}, {"id": "E.4", "text": "Confirmar dissipação completa de toda a energia residual (pressão, energia cinética/potencial armazenada, energia elétrica residual) antes de qualquer intervenção em zona de perigo", "hint": "Verificar se o procedimento inclui passo de confirmação (ex: manómetro a zero, calços colocados, órgãos móveis parados) antes da entrada na zona de perigo."}]}, {"id": "F", "title": "F — RISCOS ELÉTRICOS (Pontos 5 e 6 do DL 50/2005, Anexo I)", "items": [{"id": "F.1", "text": "Quadro elétrico com sinal de perigo elétrico visível (EN ISO 7010 — W012)", "hint": "Verificar se a porta do quadro tem o triângulo amarelo com raio. Se não tiver = NC fácil de corrigir (autocolante normalizado)."}, {"id": "F.2", "text": "Quadro elétrico fechado durante operação; sem danos na porta ou vedação", "hint": "A porta deve fechar completamente e de preferência com fecho. Verificar aberturas, furos ou entradas de cabo sem vedação."}, {"id": "F.3", "text": "Cablagem elétrica sem danos; isolamento íntegro; sem contacto com óleo, fluidos ou superfícies quentes", "hint": "Inspecionar cabos visíveis externamente ao quadro: isolamento sem fissuras ou zonas peladas. Atenção especial a cabos de pedais/comandos móveis, sujeitos a movimento e abrasão."}, {"id": "F.4", "text": "Ligação à terra da carcaça do motor e da estrutura do equipamento verificável visualmente", "hint": "Verificar cabo de terra visível na carcaça do motor elétrico e ligação à terra da estrutura do equipamento."}]}, {"id": "G", "title": "G — DOCUMENTAÇÃO (Ponto 10 do DL 50/2005, Anexo I)", "items": [{"id": "G.1", "text": "Chapa de identificação do equipamento — fabricante, modelo, nº série, ano, capacidade máxima", "hint": "Se não existir chapa = NC. Recomendação: fabricar e instalar chapa metálica com os dados disponíveis (catálogo/registos internos), identificando claramente que se trata de reconstituição."}, {"id": "G.2", "text": "Manual de instruções em português disponível e acessível ao operador", "hint": "Um catálogo comercial não substitui um manual de operação/segurança. Se não existir manual adequado, é necessário elaborar instrução interna. Não há obrigação de CE para equipamentos anteriores a 1995."}, {"id": "G.3", "text": "Equipamento anterior a 01/01/1995: avaliação de conformidade por equivalência documentada (Anexo II DL 50/2005)", "hint": "Aplicável apenas a equipamentos com essa idade. Quando aplicável, o presente relatório constitui a avaliação das condições de segurança exigida pelo DL 50/2005."}, {"id": "G.4", "text": "Plano de manutenção preventiva existente e atualizado", "hint": "Verificar plano escrito com periodicidade definida (lubrificação, substituição de fluidos, inspeção de componentes críticos, verificação de vedantes/travões/cabos, conforme aplicável)."}, {"id": "G.5", "text": "Registos de inspeções e intervenções de manutenção disponíveis", "hint": "Consultar registos existentes: que trabalhos foram feitos, por quem e quando. A ausência de registos é, por si só, uma NC de documentação."}, {"id": "G.6", "text": "Instruções de operação e segurança elaboradas internamente em português", "hint": "Se não existir manual adequado do fabricante: elaborar instrução interna com sequência de arranque/paragem, EPI obrigatórios, proibições, procedimento de emergência e contactos."}, {"id": "G.7", "text": "FDS dos fluidos/produtos utilizados no equipamento (óleos, lubrificantes, produtos químicos) disponível; código LER correto nos registos de resíduos", "hint": "Identificar o(s) fluido(s)/produto(s) utilizados. FDS deve estar acessível. Verificar se o código LER usado nos registos de resíduos corresponde ao processo gerador, não à aparência do resíduo."}, {"id": "G.8", "text": "Lista de EPI obrigatórios afixada junto ao equipamento; EPI disponíveis e em bom estado", "hint": "Verificar lista afixada e disponibilidade física dos EPI adequados ao equipamento (calçado, luvas, óculos, proteção auditiva, proteção respiratória, conforme risco identificado)."}]}, {"id": "H", "title": "H — REQUISITOS COMPLEMENTARES (equipamentos móveis / elevação — avaliar aplicabilidade; ver módulo técnico de elevação/movimentação quando aplicável)", "items": [{"id": "H.1", "text": "Equipamentos que transportam trabalhadores / risco de capotamento", "hint": "Aplicável quando o equipamento em análise transporta trabalhadores ou é um equipamento móvel com risco de capotamento (ver módulo técnico de elevação/movimentação). Marcar NA caso contrário."}, {"id": "H.2", "text": "Transmissão de energia entre equipamentos automotores", "hint": "Aplicável a equipamentos automotores com transmissão de energia entre unidades (ver módulo técnico). Marcar NA caso contrário."}, {"id": "H.3", "text": "Equipamentos de elevação ou transporte de trabalhadores", "hint": "Aplicável a equipamentos de elevação/transporte de trabalhadores (ver módulo técnico de elevação/movimentação). Marcar NA caso contrário."}]}]}};